const dataBR=(d?:string|null)=>d?d.split('-').reverse().join('/'):'—'
const situacaoPrazo=(prazo?:string|null,concluida=false)=>{
  if(!prazo||concluida)return null
  const partes=/^(\d{4})-(\d{2})-(\d{2})/.exec(prazo)
  if(!partes)return null
  const hoje=new Date()
  const diaAtual=Date.UTC(hoje.getFullYear(),hoje.getMonth(),hoje.getDate())
  const diaPrazo=Date.UTC(Number(partes[1]),Number(partes[2])-1,Number(partes[3]))
  const dias=Math.round((diaPrazo-diaAtual)/86400000)
  if(dias<0)return {cor:'#ef4444',texto:`Atrasada há ${-dias} ${dias===-1?'dia':'dias'}`}
  if(dias===0)return {cor:'#facc15',texto:'Vence hoje'}
  if(dias<=2)return {cor:'#22c55e',texto:dias===1?'Vence amanhã':'Vence em 2 dias'}
  return {cor:'#9ca3af',texto:`Faltam ${dias} dias`}
}
